SELECT SUM(l.l_extendedprice*(1-l.l_discount)) AS revenue FROM tpch_lineitem l JOIN tpch_part p ON p.p_partkey=l.l_partkey WHERE ((p.p_brand='Brand#12' AND p.p_container IN ('SM BOX','SM CASE') AND l.l_quantity BETWEEN 1 AND 11 AND p.p_size BETWEEN 1 AND 5) OR (p.p_brand='Brand#23' AND p.p_container IN ('MED BAG','MED BOX') AND l.l_quantity BETWEEN 10 AND 20 AND p.p_size BETWEEN 1 AND 10) OR (p.p_brand='Brand#34' AND p.p_container IN ('LG CASE','LG PACK') AND l.l_quantity BETWEEN 20 AND 30 AND p.p_size BETWEEN 1 AND 15)) AND l.l_shipmode IN ('AIR','REG AIR') AND l.l_shipinstruct='DELIVER IN PERSON';
